   "import { COPY as IE_COPY, s3Copy } from './item-edit-logic.js';\nimport { s4Copy, nProd } from './render.js';   // STRUCTURE S4-F: the addendum's panel lines (⟦s4.key⟧ until approved)   // «Quitar del menú» (Q-11): the approved «sección vacía» lines\n",
